/**
 * The spring tiers every AICL surface moves on.
 *
 * Three tiers, and the rule that picks between them: **the bigger the thing
 * that moves, the slower the spring.** A hover highlight, a focus ring and a
 * tooltip move a few pixels and settle almost immediately. A dropdown
 * indicator travels. A dialog takes over the view. Nothing invents its own
 * duration — it reaches for a tier, so unrelated parts of the interface move
 * at consistent magnitudes.
 *
 * Each tier carries its own exit. An exit is a plain tween one tier quicker,
 * never the entrance played backwards: a dismissal should read as crisp and
 * final, not as the entrance replayed. Every enter/exit pair below is
 * constructed so the exit is always faster than the enter it belongs to.
 */

export type SpringTier = 'fast' | 'moderate' | 'slow';

/** A spring's shape. `duration` is the settle time in seconds. */
export interface SpringSpec {
  /** Time to settle, in seconds. */
  readonly duration: number;
  /**
   * Overshoot as a fraction: `0` never passes the target, `0.12` peaks 12%
   * past it. Only the largest tier overshoots at all.
   */
  readonly bounce: number;
}

export interface SpringTierSpec extends SpringSpec {
  /** The matching exit: a tween, one tier quicker than the entrance. */
  readonly exit: { readonly duration: number };
}

export const spring = {
  /**
   * 0.08s — hovers, focus rings, fades, tooltips, selection indicators.
   * The smallest travel and the shortest settle.
   */
  fast: {
    duration: 0.08,
    bounce: 0,
    exit: { duration: 0.06 },
  },
  /**
   * 0.16s — indicators that travel: dropdown and tab pills, switch thumbs,
   * panels and drawers that must land exactly, without a wobble.
   */
  moderate: {
    duration: 0.16,
    bounce: 0,
    exit: { duration: 0.12 },
  },
  /**
   * 0.24s — large surfaces: dialogs, side panels, stepped flows. The only
   * tier that overshoots, and only just.
   */
  slow: {
    duration: 0.24,
    bounce: 0.12,
    exit: { duration: 0.16 },
  },
} as const satisfies Record<SpringTier, SpringTierSpec>;

export const springTiers: readonly SpringTier[] = ['fast', 'moderate', 'slow'];

/** The spec of one tier. */
export function springSpec(tier: SpringTier): SpringTierSpec {
  return spring[tier];
}

/**
 * The fallback delay for a deferred unmount that guards an exit animation.
 *
 * A surface that animates out needs to stay mounted until the animation
 * ends, but a throttled or backgrounded tab can stall the animation
 * indefinitely. A timer force-removes the surface after the exit duration
 * plus a safety buffer. Deriving it from the token keeps the timer in step
 * with the motion instead of drifting from it.
 */
export function exitFallbackMs(tier: SpringTier): number {
  return Math.round(spring[tier].exit.duration * 1000) + 100;
}

/**
 * Springs as CSS `linear()` easing functions.
 *
 * A spring is not a curve you can name — it is a physical response whose
 * shape depends on its damping. But CSS can express one: `linear()` takes a
 * list of stops and interpolates between them, and its output is not clamped
 * to `[0, 1]`, so an overshoot survives the trip.
 *
 * That means the whole motion system ships as plain CSS. No animation
 * runtime, no JavaScript on the critical path, and the same easing in a
 * stylesheet, a `transition`, and a Web Animations call.
 *
 * The sampler below models a damped harmonic oscillator driven to a target
 * of 1:
 *
 *   x(t) = 1 - e^(-ζωt) · (cos(ω_d t) + (ζω / ω_d) · sin(ω_d t))
 *
 * with `ζ` the damping ratio, `ω` the natural frequency and `ω_d` the damped
 * frequency. `ζ = 1` is critical damping — it arrives once and stays. `ζ < 1`
 * overshoots by exactly the tier's `bounce` fraction, because the damping
 * ratio is derived from it rather than the other way round.
 */

import { spring, springTiers, type SpringSpec, type SpringTier } from './springs.js';

/**
 * The damping ratio that produces a given overshoot.
 *
 * `bounce: 0` is critical damping (ζ = 1): the response never passes the
 * target. `bounce: 0.12` peaks 12% past it, which is ζ ≈ 0.56. Larger
 * values approach a bouncing ball (ζ → 0).
 */
export function dampingRatio(bounce: number): number {
  if (bounce <= 0) return 1;
  const l = Math.log(bounce);
  return -l / Math.sqrt(Math.PI * Math.PI + l * l);
}

/**
 * The natural frequency for a spring of a given duration.
 *
 * The response must be settled by the end of the duration, so ω is chosen so
 * the decaying envelope has fallen to 0.1% of its initial size at `t =
 * duration`. Critical damping is tighter than that envelope bound implies —
 * its error is `(1 + ωt)·e^(-ωt)` — so it gets a larger constant that lands
 * the response at 0.1% error exactly when the duration says it should.
 */
export function naturalFrequency(spec: SpringSpec): number {
  const zeta = dampingRatio(spec.bounce);
  if (zeta >= 1) return 9.1182 / spec.duration;
  return 6.9078 / (zeta * spec.duration);
}

/**
 * The spring's progress at time `t` (seconds since the start), as a number
 * that reaches 1 at the target. May exceed 1 while overshooting.
 */
export function springProgress(spec: SpringSpec, t: number): number {
  const omega = naturalFrequency(spec);
  const zeta = dampingRatio(spec.bounce);

  if (t <= 0) return 0;

  if (zeta >= 1) {
    // Critically damped: no oscillation, monotonic approach.
    return 1 - (1 + omega * t) * Math.exp(-omega * t);
  }

  const omegaD = omega * Math.sqrt(1 - zeta * zeta);
  const envelope = Math.exp(-zeta * omega * t);
  return (
    1 -
    envelope * (Math.cos(omegaD * t) + ((zeta * omega) / omegaD) * Math.sin(omegaD * t))
  );
}

/** The number of stops a spring is sampled at. */
const DEFAULT_SAMPLES = 48;

/**
 * Sample a spring into progress values, evenly spaced over its duration.
 * The first sample is 0 and the last is 1.
 */
export function sampleSpring(spec: SpringSpec, samples = DEFAULT_SAMPLES): number[] {
  const count = Math.max(2, samples);
  const out: number[] = [];
  for (let i = 0; i < count; i += 1) {
    const t = (i / (count - 1)) * spec.duration;
    out.push(springProgress(spec, t));
  }
  out[0] = 0;
  out[out.length - 1] = 1;
  return out;
}

/**
 * Render a spring as a CSS `linear()` easing function.
 *
 * The stops are the sampled progress values; the percentages are the
 * normalised times. Values are rounded to four decimals, which is well
 * under what the eye resolves and keeps the emitted CSS short.
 */
export function springEasing(spec: SpringSpec, samples = DEFAULT_SAMPLES): string {
  const values = sampleSpring(spec, samples);
  const stops = values.map((value, i) => {
    const rounded = Math.round(value * 10000) / 10000;
    const percent = Math.round((i / (values.length - 1)) * 10000) / 100;
    return i === 0 ? '0' : `${rounded} ${percent}%`;
  });
  return `linear(${stops.join(', ')})`;
}

/**
 * The CSS easing for every tier, ready to be written into a stylesheet.
 *
 * `exit` is a plain tween at the exit duration — the exit of a spring is not
 * a spring, and it is one tier quicker than the entrance it belongs to.
 */
export function springEasings(): Record<SpringTier, { enter: string; exit: string }> {
  const out = {} as Record<SpringTier, { enter: string; exit: string }>;
  for (const tier of springTiers) {
    out[tier] = {
      enter: springEasing(spring[tier]),
      exit: exitEasing,
    };
  }
  return out;
}

/**
 * The easing of an exit.
 *
 * A tween, not a spring: a dismissal should read as crisp and final rather
 * than as the entrance replayed. A `linear()` stop list cannot express this,
 * because `linear()` accepts numbers and percentages but never a time.
 */
export const exitEasing = 'cubic-bezier(0.4, 0, 1, 1)';

/**
 * Geometry for fluid hover.
 *
 * Fluid hover is one highlight per list. The highlight sits under the
 * pointer, and when the pointer moves to the next row it *travels* there
 * instead of blinking out and blinking in. The user sees where a click will
 * land before they click.
 *
 * The rule is small enough to be a pure function, and it is kept pure so it
 * can be tested without a browser:
 *
 *   1. An item the pointer is inside wins. Always, on every axis.
 *   2. Otherwise the item whose centre is nearest wins — along the list's
 *      axis for a list, in both axes for a grid. A pointer in the gap
 *      between two rows, in the container's padding, or past the last row
 *      still lands on something.
 *   3. Disabled items are skipped, but they stay in the set. A row that is
 *      mounted while clipped out of view keeps its slot, so removing it
 *      would invalidate every measurement.
 *   4. Ties keep the earlier item.
 */

/** A rectangle in container-local coordinates. */
export interface Rect {
  top: number;
  height: number;
  left: number;
  width: number;
}

/** A point in container-local coordinates. */
export interface Point {
  x: number;
  y: number;
}

/**
 * The axis a list resolves its nearest item along.
 *
 * `y` for vertical lists, `x` for horizontal strips, `xy` for grids, where
 * the straight line to each item's centre decides.
 */
export type HoverAxis = 'x' | 'y' | 'xy';

export interface PickNearestOptions {
  /** Defaults to `y`. */
  axis?: HoverAxis;
  /** Skips an item without removing it from the set. */
  isDisabled?: (index: number) => boolean;
}

/** The centre of a rectangle. */
export function centerOf(rect: Rect): Point {
  return {
    x: rect.left + rect.width / 2,
    y: rect.top + rect.height / 2,
  };
}

/** Whether a point is inside a rectangle. */
export function containsPoint(rect: Rect, point: Point): boolean {
  return (
    point.x >= rect.left &&
    point.x < rect.left + rect.width &&
    point.y >= rect.top &&
    point.y < rect.top + rect.height
  );
}

/** The distance from a point to a rectangle's centre, along one axis or in a straight line. */
export function distanceToCenter(rect: Rect, point: Point, axis: HoverAxis): number {
  const center = centerOf(rect);
  if (axis === 'x') return Math.abs(point.x - center.x);
  if (axis === 'y') return Math.abs(point.y - center.y);
  const dx = point.x - center.x;
  const dy = point.y - center.y;
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * The index of the item the pointer resolves to, or `null` when the set is
 * empty.
 *
 * `rects` is sparse: a slot for an item that has not registered yet is
 * `undefined` and is skipped.
 */
export function pickNearest(
  point: Point,
  rects: readonly (Rect | undefined)[],
  options: PickNearestOptions = {},
): number | null {
  const axis = options.axis ?? 'y';

  // 1. The item under the pointer wins.
  for (let i = 0; i < rects.length; i += 1) {
    const rect = rects[i];
    if (!rect) continue;
    if (options.isDisabled?.(i)) continue;
    if (containsPoint(rect, point)) return i;
  }

  // 2. Otherwise the nearest centre.
  let bestIndex: number | null = null;
  let bestDistance = Number.POSITIVE_INFINITY;
  for (let i = 0; i < rects.length; i += 1) {
    const rect = rects[i];
    if (!rect) continue;
    if (options.isDisabled?.(i)) continue;
    const distance = distanceToCenter(rect, point, axis);
    if (distance < bestDistance) {
      bestDistance = distance;
      bestIndex = i;
    }
  }

  return bestIndex;
}

/** A viewport point expressed in a container's local coordinates. */
export function toLocalPoint(point: Point, containerRect: Rect): Point {
  return {
    x: point.x - containerRect.left,
    y: point.y - containerRect.top,
  };
}

/**
 * The AICL motion system.
 *
 * Three spring tiers, and the rule that picks between them: the bigger the
 * thing that moves, the slower the spring. A hover highlight, a focus ring
 * and a tooltip move a few pixels; a dropdown indicator travels; a dialog
 * takes over the view. Nothing invents its own duration.
 *
 * The springs are real springs, encoded as CSS `linear()` easing functions.
 * A `linear()` stop list is not clamped to [0, 1], so the slow tier's
 * overshoot survives the trip. The curves are generated from the tokens in
 * `src/springs.ts` by `scripts/generate-motion-css.mjs`; the TypeScript is
 * the source of truth.
 *
 * Import this **after** `@aicl/styles`:
 *
 *   import '@aicl/styles';
 *   import '@aicl/motion/motion.css';
 *
 * It replaces the contract's easings with springs, so a stylesheet that says
 * `transition: opacity var(--aicl-anim) var(--aicl-ease)` becomes a spring
 * without a single line changing. It also adds the two interaction patterns
 * that need more than a duration: the travelling hover highlight, and weight
 * without reflow.
 */

/* ─── Tokens ────────────────────────────────────────────────────── */

:root {
  /* The shape of a critically damped spring: arrives once, stays. */
  --aicl-ease-spring: linear(0, 0.0166 2.13%, 0.0584 4.26%, 0.116 6.38%, 0.1826 8.51%, 0.2532 10.64%, 0.3243 12.77%, 0.3936 14.89%, 0.4594 17.02%, 0.5209 19.15%, 0.5775 21.28%, 0.6291 23.4%, 0.6756 25.53%, 0.7172 27.66%, 0.7542 29.79%, 0.787 31.91%, 0.8159 34.04%, 0.8412 36.17%, 0.8633 38.3%, 0.8825 40.43%, 0.8992 42.55%, 0.9137 44.68%, 0.9262 46.81%, 0.937 48.94%, 0.9462 51.06%, 0.9542 53.19%, 0.961 55.32%, 0.9669 57.45%, 0.9719 59.57%, 0.9761 61.7%, 0.9798 63.83%, 0.9829 65.96%, 0.9855 68.09%, 0.9877 70.21%, 0.9896 72.34%, 0.9912 74.47%, 0.9926 76.6%, 0.9938 78.72%, 0.9947 80.85%, 0.9956 82.98%, 0.9963 85.11%, 0.9969 87.23%, 0.9974 89.36%, 0.9978 91.49%, 0.9981 93.62%, 0.9984 95.74%, 0.9987 97.87%, 1 100%);

  /* The shape of the one tier that overshoots. */
  --aicl-ease-spring-bounce: linear(0, 0.0312 2.13%, 0.112 4.26%, 0.2251 6.38%, 0.3555 8.51%, 0.4909 10.64%, 0.6222 12.77%, 0.7425 14.89%, 0.8474 17.02%, 0.9347 19.15%, 1.0037 21.28%, 1.0548 23.4%, 1.0897 25.53%, 1.1104 27.66%, 1.1192 29.79%, 1.1187 31.91%, 1.1113 34.04%, 1.0991 36.17%, 1.0842 38.3%, 1.068 40.43%, 1.0519 42.55%, 1.0369 44.68%, 1.0234 46.81%, 1.012 48.94%, 1.0028 51.06%, 0.9958 53.19%, 0.9908 55.32%, 0.9876 57.45%, 0.986 59.57%, 0.9856 61.7%, 0.9862 63.83%, 0.9874 65.96%, 0.9891 68.09%, 0.991 70.21%, 0.993 72.34%, 0.9948 74.47%, 0.9965 76.6%, 0.998 78.72%, 0.9992 80.85%, 1.0002 82.98%, 1.0009 85.11%, 1.0013 87.23%, 1.0016 89.36%, 1.0017 91.49%, 1.0017 93.62%, 1.0016 95.74%, 1.0014 97.87%, 1 100%);

  /* The contract's easings, replaced. These are the names existing
     stylesheets already use, so this is the whole upgrade. */
  --aicl-ease: var(--aicl-ease-spring);
  --aicl-ease-out: var(--aicl-ease-spring-bounce);
  --aicl-ease-in: cubic-bezier(0.4, 0, 1, 1);

  /* The tiers, as one shorthand each: duration and shape together, so a
     component cannot pick a slow duration and a fast shape by accident.
     The contract's `--aicl-anim-*` names stay durations. */
  --aicl-motion-fast: 80ms var(--aicl-ease-spring);
  --aicl-motion-moderate: 160ms var(--aicl-ease-spring);
  --aicl-motion-slow: 240ms var(--aicl-ease-spring-bounce);

  /* Exits. Always a tween, always one tier quicker than the entrance it
     belongs to, so a dismissal reads as crisp and final rather than as the
     entrance replayed. */
  --aicl-motion-fast-exit: 60ms var(--aicl-ease-in);
  --aicl-motion-moderate-exit: 120ms var(--aicl-ease-in);
  --aicl-motion-slow-exit: 160ms var(--aicl-ease-in);

  /* Font weight tokens for weight without reflow. Each pairs a `wght` with
     an `opsz` so the advance width barely changes when the weight does:
     a heavier weight widens the glyphs and a tighter optical size pulls them
     back. Needs a variable font with both axes. */
  --aicl-weight-normal: 'wght' 400, 'opsz' 14;
  --aicl-weight-medium: 'wght' 500, 'opsz' 16;
  --aicl-weight-semibold: 'wght' 550, 'opsz' 18;
  --aicl-weight-bold: 'wght' 700, 'opsz' 25;
}

/* ─── Fluid hover ───────────────────────────────────────────────── */

/* One highlight per list. It travels under the cursor instead of blinking
   between rows, so the user sees where a click will land before they click.
   The travel is a transform, so it stays on the compositor and reduced
   motion can drop it for free. */
[data-aicl-fluid-hover] {
  background: var(--aicl-hover-bg);
  border-radius: var(--aicl-radius-sm);
  transition:
    transform var(--aicl-motion-fast),
    width var(--aicl-motion-fast),
    height var(--aicl-motion-fast),
    opacity var(--aicl-motion-fast);
}

/* A fresh entry lands on the row it is on rather than sliding over from
   wherever the highlight was last. */
[data-aicl-fluid-hover][data-snap] {
  transition: opacity var(--aicl-motion-fast);
}

/* ─── Weight without reflow ─────────────────────────────────────── */

/* The ghost span reserves the width at the heaviest weight the label can
   take. The visible copy changes weight inside that reserved space, so no
   neighbour moves. */
[data-aicl-weight] {
  display: inline-grid;
  position: relative;
}

[data-aicl-weight] > * {
  grid-area: 1 / 1;
}

[data-aicl-weight-ghost] {
  visibility: hidden;
  font-variation-settings: var(--aicl-weight-semibold);
}

[data-aicl-weight-text] {
  font-variation-settings: var(--aicl-weight-normal);
  transition: font-variation-settings var(--aicl-motion-fast);
}

[data-aicl-weight-text][data-weight='medium'] {
  font-variation-settings: var(--aicl-weight-medium);
}

[data-aicl-weight-text][data-weight='semibold'] {
  font-variation-settings: var(--aicl-weight-semibold);
}

[data-aicl-weight-text][data-weight='bold'] {
  font-variation-settings: var(--aicl-weight-bold);
}

/* ─── Reduced motion ────────────────────────────────────────────── */

/* Fewer and gentler, not none. Opacity and colour keep their fades — they
   help comprehension — but the travel is dropped, so the highlight lands
   where it belongs instead of gliding there. */
@media (prefers-reduced-motion: reduce) {
  [data-aicl-fluid-hover] {
    transition: opacity var(--aicl-motion-fast) var(--aicl-ease-in);
  }

  [data-aicl-weight-text] {
    transition: none;
  }
}
